-- HARAZD WAREHOUSE / PACKAGING. Execute in Supabase SQL Editor.
create sequence if not exists public.packaging_pk_seq;
create table if not exists public.packaging (id uuid primary key default gen_random_uuid(),pk_id text unique default ('PK-'||lpad(nextval('public.packaging_pk_seq')::text,6,'0')),name text not null check(length(trim(name))>0),kind text not null check(kind in ('rack','case','box','pallet','other')),mode text not null default 'flex' check(mode in ('fixed','flex')),manufacturer text,model text,description text,length_mm numeric check(length_mm>=0),width_mm numeric check(width_mm>=0),height_mm numeric check(height_mm>=0),empty_weight_kg numeric check(empty_weight_kg>=0),max_payload_kg numeric check(max_payload_kg>=0),rack_u integer check(rack_u>=0),rack_depth_mm numeric check(rack_depth_mm>=0),location text,custom_fields jsonb not null default '[]'::jsonb,parent_id uuid references public.packaging(id) on delete restrict,created_at timestamptz default now(),updated_at timestamptz default now(),constraint packaging_no_self check(parent_id is distinct from id));
create or replace function public.packaging_guard_cycle() returns trigger language plpgsql set search_path=public as $$ declare cursor_id uuid;visited uuid[]:=array[new.id];begin cursor_id:=new.parent_id;while cursor_id is not null loop if cursor_id=any(visited) then raise exception 'Циклічне вкладення заборонено';end if;visited:=array_append(visited,cursor_id);select parent_id into cursor_id from public.packaging where id=cursor_id;end loop;new.updated_at:=now();return new;end $$;
drop trigger if exists packaging_guard on public.packaging;create trigger packaging_guard before insert or update on public.packaging for each row execute function public.packaging_guard_cycle();
create table if not exists public.packaging_plan(id uuid primary key default gen_random_uuid(),packaging_id uuid not null references public.packaging(id) on delete cascade,equipment_id uuid references public.equipment(id) on delete restrict,item_name text not null,quantity numeric not null default 1 check(quantity>0),created_at timestamptz default now());
create table if not exists public.packaging_contents(id uuid primary key default gen_random_uuid(),packaging_id uuid not null references public.packaging(id) on delete cascade,equipment_id uuid not null references public.equipment(id) on delete restrict,quantity numeric not null default 1 check(quantity>0),created_at timestamptz default now(),unique(equipment_id));
create table if not exists public.packaging_history(id bigint generated always as identity primary key,packaging_id uuid references public.packaging(id) on delete set null,action text not null,details jsonb not null default '{}'::jsonb,actor uuid default auth.uid(),created_at timestamptz default now());
create or replace function public.packaging_audit() returns trigger language plpgsql security definer set search_path=public as $$declare target_id uuid;begin if tg_op='DELETE' then target_id:=old.packaging_id;else target_id:=new.packaging_id;end if;insert into public.packaging_history(packaging_id,action,details,actor) values(target_id,tg_op,jsonb_build_object('table',tg_table_name,'before',case when tg_op='INSERT' then null else to_jsonb(old) end,'after',case when tg_op='DELETE' then null else to_jsonb(new) end),auth.uid());if tg_op='DELETE' then return old;else return new;end if;end $$;
drop trigger if exists packaging_contents_audit on public.packaging_contents;create trigger packaging_contents_audit after insert or update or delete on public.packaging_contents for each row execute function public.packaging_audit();
drop trigger if exists packaging_plan_audit on public.packaging_plan;create trigger packaging_plan_audit after insert or update or delete on public.packaging_plan for each row execute function public.packaging_audit();
create or replace function public.packaging_parent_audit() returns trigger language plpgsql security definer set search_path=public as $$begin if old.parent_id is distinct from new.parent_id then insert into public.packaging_history(packaging_id,action,details,actor) values(new.id,'MOVE',jsonb_build_object('old_parent',old.parent_id,'new_parent',new.parent_id),auth.uid());end if;return new;end $$;
drop trigger if exists packaging_parent_audit on public.packaging;create trigger packaging_parent_audit after update of parent_id on public.packaging for each row execute function public.packaging_parent_audit();
do $$declare t text;begin foreach t in array array['packaging','packaging_plan','packaging_contents','packaging_history'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists packaging_read on public.%I',t);execute format('create policy packaging_read on public.%I for select to authenticated using (public.warehouse_can(''equipment_view'') or public.warehouse_can(''equipment_edit''))',t);end loop;foreach t in array array['packaging','packaging_plan','packaging_contents'] loop execute format('drop policy if exists packaging_write on public.%I',t);execute format('create policy packaging_write on public.%I for all to authenticated using (public.warehouse_can(''equipment_edit'')) with check (public.warehouse_can(''equipment_edit''))',t);end loop;end $$;
notify pgrst,'reload schema';
grant usage on sequence public.packaging_pk_seq to authenticated;
